interface ApiResponse {
  id: number;
  title: string;
}

@Injectable({
  providedIn: 'root'
})
export class DataService {
  constructor(private http: HttpClient) {}

  fetchData() {
    return this.http.get<ApiResponse>('https://jsonplaceholder.typicode.com/posts/1');
